parameters.jsCode:
let rawText = $json.output || "";
rawText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

let parsedData = {};

try {
  parsedData = JSON.parse(rawText);
} catch (error) {
  parsedData = {
    respuesta: rawText,
    es_cita: false
  };
}

return {
  respuesta: parsedData.respuesta || rawText,
  es_cita: Boolean(parsedData.es_cita),
  confirmar_cita: Boolean(parsedData.es_cita), // Necesario para la condición del nodo IF
  fecha_inicio: parsedData.fecha_inicio || null,
  tipo_tramite: parsedData.tipo_tramite || null
};

// 1. Extraer los datos del callback del botón
const callbackData = $json.callback_query?.data || "";
const partes = callbackData.split('|'); 

// Extraer fecha y tipo de trámite pasados en el botón
const fechaInicio = partes[1] || "";
const tipoTramite = partes[2] || "Trámite de Extranjería";

// 2. Extraer el nombre del usuario directamente desde su perfil de Telegram
const primerNombre = $json.callback_query?.from?.first_name || "";
const apellido = $json.callback_query?.from?.last_name || "";
const nombreCompleto = `${primerNombre} ${apellido}`.trim() || "Cliente Telegram";

// 3. Devolver la estructura exacta (los 5 campos) para el subflujo de citas
return {
  accion: "crear",
  nombre_cliente: nombreCompleto,
  tipo_tramite: tipoTramite,
  fecha_inicio: fechaInicio,
  event_id: "",
  // Variables auxiliares para responder a Telegram después
  callback_query_id: $json.callback_query?.id,
  chat_id: $json.callback_query?.message?.chat?.id
};

